#!/bin/sh
# Name: KFX DeDRM
# Author: Satsuoni & Jadehawk
# Icon: data:image/png;base64,
# DontUseFBInk

BASE="/mnt/us/kfxdedrm-scriptlet"
MENU="$BASE/bin/menu.sh"
KTERM="/mnt/us/extensions/kterm/bin/kterm"
FBINK="/mnt/us/libkh/bin/fbink"

show_message() {
    if [ -x "$FBINK" ]; then
        "$FBINK" -k >/dev/null 2>&1
        "$FBINK" -y 5 -S 3 "$1" >/dev/null 2>&1
        [ -n "$2" ] && "$FBINK" -y 9 -S 2 "$2" >/dev/null 2>&1
    else
        printf '%s\n' "$1"
        [ -n "$2" ] && printf '%s\n' "$2"
    fi
}

if [ ! -x "$MENU" ]; then
    show_message "KFX DeDRM menu missing" "$MENU"
    exit 1
fi

if [ ! -x "$KTERM" ]; then
    show_message "kterm is required" "Install it to /mnt/us/extensions/kterm"
    exit 1
fi

# KindleFetch uses this same kterm launch pattern. Keep kterm in the foreground so
# SH_Integration sees a normal child exit and returns cleanly to the Library.
exec "$KTERM" -e "sh $MENU" -k 1 -o U -s 7
